-- B4 base-role permissions (PLAN B4 section 3). 0007, 0106, 0206 and 0304 cannot change; this brings the roles B4 extends to
-- BASE_ROLES, and Support agent to MFA (bank-detail requests need step-up, AC-17.2). Generated by
-- renderBaseRoleUpdate(B4_UPDATED_BASE_ROLES) and renderBaseRoleMfaUpdate(B4_MFA_CHANGED_BASE_ROLES) in
-- apps/api/src/lib/permissions.ts; apps/api/src/lib/permissions.test.ts fails if this block and the catalogue differ.
UPDATE role SET permissions = '{user.manage,settings.manage,import.manage,mapping.edit,mapping.approve,compliance.read,audit.read,vendor_access.decide,market.manage,integration.manage,participant.read,order.read,product.manage,integration.read,ledger.export}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'Tenant admin';
UPDATE role SET permissions = '{compliance.read,participant.read,genealogy.read,case.genealogy.read,order.read,late.manage,integration.read,plan.read,period.read,run.execute,run.review,trace.read,restatement.request,case.restatement.read,ledger.read,case.adjustment.read,case.adjustment.create,case.write_off.read,case.write_off.create}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'Commission analyst';
UPDATE role SET permissions = '{compliance.read,participant.unmask,plan.activate,settings.approve,participant.read,order.read,plan.read,period.read,run.review,run.commit,trace.read,restatement.approve,case.restatement.read,ledger.read,ledger.export,payout.read,payout.approve,tax.manage,case.adjustment.read,case.adjustment.approve,case.write_off.read,case.write_off.create,case.write_off.approve,case.returned_payment.read}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'Finance approver';
UPDATE role SET permissions = '{participant.unmask,participant.read,ledger.read,payout.read,payout.prepare,payout.reconcile,payout.hold,case.bank_detail.read,case.returned_payment.read,case.returned_payment.create}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'Payout officer';
UPDATE role SET permissions = '{mapping.approve,compliance.read,snapshot.create,export,audit.read,market.signoff,participant.read,participant.terminate,participant_type.approve,agreement.publish,genealogy.read,case.genealogy.read,case.genealogy.approve,case.duplicate.read,case.duplicate.approve,order.read,plan.read,plan.approve,period.read,run.review,trace.read,restatement.request,case.restatement.read,guardrail.read,override.approve,ledger.read,payout.read,payout.hold,case.adjustment.read,case.write_off.read,case.bank_detail.read,case.bank_detail.approve}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'Compliance officer';
UPDATE role SET permissions = '{participant.read,participant.manage,genealogy.read,case.genealogy.read,case.genealogy.create,case.duplicate.read,case.duplicate.create,servicing.manage,order.read,period.read,run.review,trace.read,case.bank_detail.read,case.bank_detail.create}'::text[] WHERE is_base AND tenant_id IS NULL AND name = 'Support agent';
UPDATE role SET mfa_required = true WHERE is_base AND tenant_id IS NULL AND name IN ('Support agent');
